// Count all DISTINCT eight-row pair cliques. For each subset T of a packing, install only its mandatory cuts. Core failure is an eight; a mixed failure has 2..|T| ports and the remaining vertices in the core. No root is blue to a port.
use std::{collections::HashMap,io::{self,Read}};type A=[u32;26];const F:u32=(1<<26)-1;
fn blue(a:&A,mut p:u32,k:u32)->bool{if k==0{return true}while p.count_ones()>=k{let i=p.trailing_zeros()as usize;p&=p-1;if blue(a,p&!a[i],k-1){return true}}false}
struct Job{rows:Vec<u32>,cuts:Vec<u64>,edges:Vec<(usize,usize)>,src:A,graphs:HashMap<u64,A>,w:HashMap<(u64,u32,u32),bool>,adj:Vec<Vec<bool>>,depth:[u64;9],best:Vec<usize>,best_d:usize,tr:[u64;8],example:Vec<Vec<usize>>}
impl Job{
fn bad(&mut self,cut:u64,m:u32,k:u32)->bool{if let Some(&v)=self.w.get(&(cut,m,k)){return v}if !self.graphs.contains_key(&cut){let mut g=self.src;let mut c=cut;while c!=0{let i=c.trailing_zeros()as usize;c&=c-1;let(u,v)=self.edges[i];g[u]^=1<<v;g[v]^=1<<u}self.graphs.insert(cut,g);}let v=blue(&self.graphs[&cut],m,k);self.w.insert((cut,m,k),v);v}
fn inspect(&mut self,p:&[usize]){if std::env::var_os("ROW_LIST_STATIC").is_some(){println!("rows {:?}",p);return}let mut c=[0u64;256];let mut m=[F;256];for s in 1..256usize{let i=p[s.trailing_zeros()as usize];let t=s&(s-1);c[s]=c[t]|self.cuts[i];m[s]=m[t]&!self.rows[i]}let mut flags=0;for s in (1..256usize).filter(|s|s.count_ones()==3){if flags&1==0 && self.bad(c[s],F,8){flags|=1}if flags&2==0 && self.bad(c[s],m[s],6){flags|=2}if flags&4==0{let mut x=s;while x!=0{let pair=s^(x&x.wrapping_neg());x&=x-1;if self.bad(c[s],m[pair],7){flags|=4;break}}}if flags==7{break}}self.tr[flags]+=1;if self.tr[flags]==1{self.example[flags]=p.to_vec()}let mut d=3;if flags==0{d=8; 'depth:for k in 4..=8{for s in (1..256usize).filter(|s|s.count_ones()==k){if self.bad(c[s],F,8){d=k;break 'depth}let mut t=s;while t!=0{let n=t.count_ones();if n>=2 && self.bad(c[s],m[t],9-n){d=k;break 'depth}t=(t-1)&s}}}if d==8{let mut good=!self.bad(c[255],F,8);for t in 1..256usize{good&=!self.bad(c[255],m[t],9-t.count_ones())}if good{d=9}}}self.depth[(d-1)as usize]+=1;if d as usize>self.best_d{self.best_d=d as usize;self.best=p.to_vec()}}
fn visit(&mut self,opts:&[usize],p:&mut Vec<usize>){if p.len()==8{self.inspect(p);return}for(k,&i)in opts.iter().enumerate(){if opts.len()-k<8-p.len(){break}let q:Vec<_>=opts[k+1..].iter().copied().filter(|&j|self.adj[i][j]).collect();p.push(i);self.visit(&q,p);p.pop();}}}
fn main(){let mut l=String::new();io::stdin().read_to_string(&mut l).unwrap();let mut it=l.lines().map(|l|l.split_whitespace().map(|v|v.parse::<u32>().unwrap()).collect::<Vec<_>>());let src:A=it.next().unwrap().try_into().unwrap();let rows=it.next().unwrap();let n=rows.len();let mut j=Job{src,rows,cuts:vec![0;n],edges:vec![],graphs:HashMap::new(),w:HashMap::new(),adj:vec![vec![false;n];n],depth:[0;9],best:vec![],best_d:0,tr:[0;8],example:vec![vec![];8]};for u in 0..26{for v in u+1..26{if src[u]>>v&1!=0 && j.rows.iter().any(|r|r>>u&r>>v&1!=0){let k=j.edges.len();assert!(k<64);j.edges.push((u,v));for(i,r)in j.rows.iter().enumerate(){if r>>u&r>>v&1!=0{j.cuts[i]|=1<<k}}}}}for i in 0..n{for t in i+1..n{if !j.bad(0,F&!(j.rows[i]|j.rows[t]),7)&& (std::env::var_os("ROW_LIST_STATIC").is_some() || !j.bad(j.cuts[i]|j.cuts[t],F,8)){j.adj[i][t]=true}}}j.visit(&(0..n).collect::<Vec<_>>(),&mut vec![]);println!("{:?}\n{:?}\n{:?}\n{:?}",j.depth,j.tr,j.best,j.example)}
